import json, os, sys
from pathlib import Path
api = json.loads(Path(os.environ['FLIP_SKIP_API']).read_text())
args = sys.argv[1:]
tool = Path(sys.argv[0]).name
if tool == 'git' and args[:1] == ['-C']: args = args[2:]
with open(os.environ['FLIP_SKIP_CALLS'], 'a') as out: out.write(json.dumps([tool, *args]) + '\n')
if tool == 'git':
    if args[0] == 'fetch':
        if api.get('git_error'):
            sys.stderr.write(api['git_error']); sys.exit(1)
    elif args[:2] == ['remote', 'get-url']:
        sys.exit(1)
    elif args[0] == 'ls-tree':
        if api.get('fractal'): sys.stdout.write('100644 blob fixture\t' + args[-1] + '\0')
    elif args[0] == 'show':
        path = args[-1].split(':', 1)[1]
        if path.endswith('evidence-skip-policy.json'): print(json.dumps({'checks': api['policy']}))
        elif path.endswith('required-lanes.json'): print(json.dumps({'lanes': api.get('lanes', {})}))
        elif path == '.github/workflows/fleet.yml': sys.stdout.write(api['workflow'])
        else: raise AssertionError(args)
    else: raise AssertionError(args)
else:
    assert tool == 'gh' and args[0] == 'api', args
    path = next(arg for arg in args[1:] if arg.startswith('repos/'))
    seen = sum(1 for line in Path(os.environ['FLIP_SKIP_CALLS']).read_text().splitlines() if json.loads(line)[0] == 'gh' and path in json.loads(line)[1:])
    if api.get('fail_first') and seen <= api['fail_first']:
        sys.stderr.write('transient'); sys.exit(1)
    if '/workflows/' in path and api.get('listing'):
        mode = api['listing']
        page = int(path.rsplit('page=', 1)[1])
        ancient = {'id': 1, 'created_at': '2000-01-01T00:00:00Z', 'status': 'in_progress'}
        current = lambda i: {'id': i, 'created_at': '2026-11-20T10:00:00Z', 'status': 'in_progress'}
        if mode == 'empty': payload = {'workflow_runs': [], 'total_count': 0}
        elif mode == 'short': payload = {'workflow_runs': [ancient], 'total_count': 2}
        elif mode == 'recover': payload = {'workflow_runs': [ancient] * (1 if seen == 1 else 2), 'total_count': 2}
        elif mode == 'quiet': payload = {'workflow_runs': [dict(ancient, id=i) for i in range(100)], 'total_count': 1000}
        elif mode == 'two-pages': payload = {'workflow_runs': [current(i) for i in range(100)] if page == 1 else [ancient], 'total_count': 101}
        elif mode == 'cap': payload = {'workflow_runs': [current(page * 100 + i) for i in range(100)], 'total_count': 1001}
        else: raise AssertionError(mode)
        print(json.dumps(payload)); sys.exit(0)
    error = api.get('gh_error') or api.get('errors', {}).get(path)
    if error: sys.stderr.write(error); sys.exit(1)
    if '/workflows/' in path:
        key = path.split('/workflows/')[1].split('/')[0]
        runs = api.get('release_runs' if key == 'release-fractal.yml' else 'runs', [])
        print(json.dumps({'workflow_runs': runs, 'total_count': len(runs)}))
    elif path.endswith('/logs'):
        job = path.split('/jobs/')[1].split('/')[0]
        sys.stdout.write(api['logs'][job])
    elif '/jobs?' in path:
        run = path.split('/runs/')[1].split('/')[0]
        print(json.dumps([{'jobs': api.get('jobs', {}).get(run, [])}]))
    elif '/files?' in path:
        print(json.dumps([[{'filename': name} for name in api.get('files', [])]]))
    elif '/commits/' in path and path.endswith('/pulls'):
        print(json.dumps([{'number': 17}]))
    else: raise AssertionError(args)

